<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import {Activity,Play,Plus,RadioTower,RefreshCw,Server,Wifi} from 'lucide-vue-next';import {createCredential,deleteCredential,listCredentials,type Credential} from '@/api/cmdb'
import RemoteExecutionPanel from './RemoteExecutionPanel.vue';import RemoteAccessPanel from './RemoteAccessPanel.vue';import TaskResultModal from './TaskResultModal.vue';import KubernetesPanel from './KubernetesPanel.vue';import ExporterPanel from './ExporterPanel.vue'
import {useAuthStore} from '@/stores/useAuthStore';import {agentStatusLabel,taskProgress} from '@/features/discovery/discoveryModel'
type Agent={id:string;name:string;hostname:string;ip:string;os?:string;region?:string;status:string;version:string;lastHeartbeat:string};type Item={id:string;name:string;ip:string;state:string;result?:string;message?:string};type Task={id:string;name:string;scope:string;status:string;discovered:number;imported:number;items?:Item[]};type Summary={total:number;online:number;tasks:number;pending:number}
const auth=useAuthStore(),agents=ref<Agent[]>([]),tasks=ref<Task[]>([]),summary=ref<Summary>(),busy=ref(false),error=ref('');const agentQuery=ref(''),agentStatus=ref(''),selectedAgent=ref<Agent|null>(null),agentAsset=ref<any|null>(null);const filteredAgents=computed(()=>{const q=agentQuery.value.trim().toLowerCase();return agents.value.filter(a=>{if(agentStatus.value&&a.status!==agentStatus.value)return false;if(q&&!(a.name+' '+a.hostname+' '+a.ip+' '+(a.os||'')).toLowerCase().includes(q))return false;return true})});const headers=computed(()=>({Authorization:`Bearer ${auth.token}`,'Content-Type':'application/json'}));async function request<T>(url:string,options?:RequestInit){const r=await fetch(url,{...options,headers:headers.value});if(!r.ok){let message=`请求失败 (${r.status})`;try{const body=await r.json() as {message?:string;code?:string};message=body.message||body.code||message}catch{}throw new Error(message)}return r.json() as Promise<T>};async function load(){busy.value=true;error.value='';try{[summary.value,agents.value,tasks.value]=await Promise.all([request<Summary>('/api/v1/discovery/summary'),request<Agent[]>('/api/v1/discovery/agents'),request<Task[]>('/api/v1/discovery/tasks')])}catch(e){error.value=e instanceof Error?e.message:'加载失败'}finally{busy.value=false}};async function openAgent(a:Agent){selectedAgent.value=a;agentAsset.value=null;try{agentAsset.value=await request<any>('/api/v1/cmdb/assets/'+encodeURIComponent(a.id))}catch{agentAsset.value=null}}
function closeAgent(){selectedAgent.value=null;agentAsset.value=null}
async function createTask(){await request<Task>('/api/v1/discovery/tasks',{method:'POST',body:JSON.stringify({name:`网段扫描 ${tasks.value.length+1}`,source:'network',scope:'10.20.0.0/24'})});await load()};async function action(task:Task,type:'run'|'reconcile'){await request<Task>(`/api/v1/discovery/tasks/${task.id}/${type}`,{method:'POST'});await load()};const cidrText=ref('172.28.68.0/24\n172.28.69.0/24');const scanType=ref('physical-server');const scanPorts=ref('9100,19100');const scanning=ref(false);const scanResult=ref<{scanned:number;found:number;adopted:number;merged:number;conflicts:number}|null>(null)
async function scanNodeExporter(){scanning.value=true;error.value='';try{const cidrs=cidrText.value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);scanResult.value=await request<{scanned:number;found:number;adopted:number;merged:number;conflicts:number}>('/api/v1/discovery/scan-node-exporter',{method:'POST',body:JSON.stringify({cidrs,defaultType:scanType.value,ports:Array.from(new Set(scanPorts.value.split(/[^0-9]+/).map(Number).filter(v=>v>=1&&v<=65535))),requireApproval:requireApproval.value})});await load()}catch(e){error.value=e instanceof Error?e.message:'扫描失败'}finally{scanning.value=false}}
const sshCidrs=ref('172.28.69.161/32');const sshScanType=ref('');const sshPort=ref(22);const sshScanning=ref(false);const sshResult=ref<{scanned:number;found:number;adopted:number;merged:number;conflicts:number}|null>(null)
async function scanSSH(){sshScanning.value=true;error.value='';try{const cidrs=sshCidrs.value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);sshResult.value=await request<{scanned:number;found:number;adopted:number;merged:number;conflicts:number}>('/api/v1/discovery/scan-ssh',{method:'POST',body:JSON.stringify({cidrs,defaultType:sshScanType.value,port:sshPort.value,credentialId:sshCred.value,requireApproval:requireApproval.value})});await load()}catch(e){error.value=e instanceof Error?e.message:'SSH 扫描失败'}finally{sshScanning.value=false}}
const aiHosts=ref('172.28.68.56');const aiType=ref('');const aiPort=ref(22);const aiGateway=ref('http://172.28.69.161:30080');const aiVersion=ref('');const aiBusy=ref(false);const aiResult=ref<Array<{host:string;ok:boolean;info:string}>>([])
async function batchUninstall(){aiBusy.value=true;error.value='';try{const hosts=aiHosts.value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);aiResult.value=await request<Array<{host:string;ok:boolean;info:string}>>('/api/v1/discovery/agent-uninstall',{method:'POST',body:JSON.stringify({hosts,port:aiPort.value})})}catch(e){error.value=e instanceof Error?e.message:'批量卸载失败'}finally{aiBusy.value=false}}
async function batchInstall(){aiBusy.value=true;error.value='';try{const hosts=aiHosts.value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);aiResult.value=await request<Array<{host:string;ok:boolean;info:string}>>('/api/v1/discovery/agent-install',{method:'POST',body:JSON.stringify({hosts,assetType:aiType.value,port:aiPort.value,gatewayUrl:aiGateway.value,credentialId:aiCred.value})})}catch(e){error.value=e instanceof Error?e.message:'批量安装失败'}finally{aiBusy.value=false}}
const creds=ref<Credential[]>([]);const showCreds=ref(false);const credName=ref('');const credKind=ref('snmp');const credUser=ref('');const credSecret=ref('');const sshCred=ref('');const snmpCred=ref('');const aiCred=ref('');type Pending={taskId:string;id:string;name:string;ip:string;type:string;source:string;state:string;confidence:number;discoveredAt:string};type Audit={id:string;actor:string;action:string;target:string;detail:string;occurredAt:string}
const activeTab=ref<'overview'|'discovery'|'network'|'deploy'|'operations'|'k8s'|'exporter'>('overview');const showApprovals=ref(false);const pending=ref<Pending[]>([]);const audit=ref<Audit[]>([]);const requireApproval=ref(false);const actionBusy=ref('');const approvalMessage=ref('');const selectedTaskId=ref('')
async function loadApprovals(){try{pending.value=await request<Pending[]>('/api/v1/discovery/pending');audit.value=await request<Audit[]>('/api/v1/audit?limit=50');error.value=''}catch(e){pending.value=[];audit.value=[];error.value=e instanceof Error?e.message:'待审批与审计加载失败'}}
async function approveItem(id:string){actionBusy.value=id;approvalMessage.value='';error.value='';try{await request(`/api/v1/discovery/pending/${encodeURIComponent(id)}/approve`,{method:'POST'});approvalMessage.value=`已通过审批：${id}`;await loadApprovals();await load()}catch(e){error.value=e instanceof Error?e.message:'审批失败'}finally{actionBusy.value=''}}
async function rejectItem(id:string){actionBusy.value=id;approvalMessage.value='';error.value='';try{await request(`/api/v1/discovery/pending/${encodeURIComponent(id)}/reject`,{method:'POST'});approvalMessage.value=`已拒绝：${id}`;await loadApprovals()}catch(e){error.value=e instanceof Error?e.message:'拒绝失败'}finally{actionBusy.value=''}}
async function loadCreds(){try{creds.value=await listCredentials(auth.token)}catch{creds.value=[]}}async function addCred(){try{await createCredential(auth.token,{name:credName.value,kind:credKind.value,username:credUser.value,secret:credSecret.value});credName.value='';credUser.value='';credSecret.value='';await loadCreds()}catch(e){error.value=e instanceof Error?e.message:'凭据保存失败'}}async function removeCred(id:string){try{await deleteCredential(auth.token,id);await loadCreds()}catch(e){error.value=e instanceof Error?e.message:'凭据删除失败'}}
const snmpCidrs=ref('172.31.42.124/32');const snmpType=ref('');const snmpPort=ref(161);const snmpBusy=ref(false);const snmpResult=ref<{scanned:number;found:number;adopted:number;merged:number;conflicts:number}|null>(null)
async function scanSNMP(){snmpBusy.value=true;error.value='';try{const cidrs=snmpCidrs.value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);snmpResult.value=await request<{scanned:number;found:number;adopted:number;merged:number;conflicts:number}>('/api/v1/discovery/scan-snmp',{method:'POST',body:JSON.stringify({cidrs,defaultType:snmpType.value,port:snmpPort.value,credentialId:snmpCred.value,requireApproval:requireApproval.value})})}catch(e){error.value=e instanceof Error?e.message:'SNMP 扫描失败'}finally{snmpBusy.value=false}}
onMounted(load)
loadCreds();request<{version:string}>('/api/v1/agent/install/version').then((v)=>aiVersion.value=v.version).catch(()=>{})
</script>
<template><section class="discovery-page"><header class="discovery-heading"><div><span>AGENT & AUTO DISCOVERY</span><h1>Agent 与自动发现</h1><button @click="showCreds=true">凭据管理</button><button @click="showApprovals=true;loadApprovals()">待审批/审计</button><label class="inline-check"><input v-model="requireApproval" type="checkbox">发现需审批</label><p>统一管理采集端在线状态、发现任务与 CMDB 数据入库。</p></div></header><div v-if="error" class="discovery-error">{{error}}</div><nav class="discovery-tabs"><button :class="{active:activeTab==='overview'}" @click="activeTab='overview'"><RadioTower/>总览与任务</button><button :class="{active:activeTab==='discovery'}" @click="activeTab='discovery'"><Server/>主机发现</button><button :class="{active:activeTab==='network'}" @click="activeTab='network'"><Wifi/>网络设备</button><button :class="{active:activeTab==='deploy'}" @click="activeTab='deploy'"><Play/>Agent 部署</button><button :class="{active:activeTab==='operations'}" @click="activeTab='operations'"><Activity/>受控运维</button><button :class="{active:activeTab==='k8s'}" @click="activeTab='k8s'"><Boxes/>K8s 资源</button><button :class="{active:activeTab==='exporter'}" @click="activeTab='exporter'"><Activity/>Exporter 管理</button></nav><div class="discovery-summary"><article><RadioTower/><div><span>Agent 总数</span><strong>{{summary?.total??0}}</strong></div></article><article><Wifi/><div><span>在线 Agent</span><strong>{{summary?.online??0}}</strong></div></article><article><Activity/><div><span>待纳管资产</span><strong>{{summary?.pending??0}}</strong></div></article><article><Server/><div><span>发现任务</span><strong>{{summary?.tasks??0}}</strong></div></article></div><div class="discovery-grid" :data-tab="activeTab"><section v-if="activeTab==='overview'" class="discovery-panel"><header><div><h2>采集端状态</h2><span>实时心跳与版本</span></div><button @click="load"><RefreshCw :class="{spin:busy}"/></button></header><div class="agent-toolbar"><input v-model="agentQuery" placeholder="搜索主机名/IP/OS"><select v-model="agentStatus"><option value="">全部状态</option><option value="online">在线</option><option value="offline">离线</option></select></div>
        <div class="agent-list"><article v-for="agent in filteredAgents" :key="agent.id" @click="openAgent(agent)" class="agent-row"><i :data-status="agent.status"></i><div><strong>{{agent.name}}</strong><span>{{agent.ip}} · {{agent.hostname}} · {{agent.os||'未知OS'}} · v{{agent.version}}</span></div><b :data-status="agent.status">{{agentStatusLabel(agent.status)}}</b><time>{{agent.lastHeartbeat||'尚未连接'}}</time></article></div></section><section v-if="activeTab==='overview'" class="discovery-panel tasks"><header><div><h2>发现任务</h2><span>扫描、识别并纳管基础设施</span></div></header><article v-for="task in tasks" :key="task.id" class="task-card"><div class="task-title"><div><strong>{{task.name}}</strong><span>{{task.scope}}</span></div><b>{{task.status}}</b></div><div class="task-counts"><span>已发现 <strong>{{task.discovered}}</strong></span><span>已入库 <strong>{{task.imported}}</strong></span><span>纳管率 <strong>{{taskProgress(task)}}%</strong></span></div><div class="task-progress"><i :style="{width:taskProgress(task)+'%'}"></i></div><div v-if="task.items?.length" class="discovered-items"><span v-for="item in task.items" :key="item.id"><Server/>{{item.name}}<small>{{item.ip}}</small><b>{{item.result||item.state}}</b></span></div><footer><button @click.stop="selectedTaskId=task.id">结果明细</button></footer></article></section><section v-if="activeTab==='discovery'" class="discovery-panel scanner"><header><div><h2>node_exporter 网段扫描</h2><span>输入网段和候选端口（如 9100,19100），自动识别每台主机的实际端口并纳管到 CMDB</span></div></header><div class="scanner-form"><label><span>网段（每行一个）</span><textarea v-model="cidrText" rows="3"></textarea></label><label><span>node_exporter 端口（可多个）</span><input v-model="scanPorts" placeholder="9100,19100"></label><label><span>资产类型</span><select v-model="scanType"><option value="">自动识别（默认物理机）</option><option value="physical-server">物理服务器</option><option value="virtual-machine">虚拟机</option></select></label><button class="primary" :disabled="scanning" @click="scanNodeExporter">{{scanning?'扫描中...':'开始扫描并纳管'}}</button></div><div v-if="scanResult" class="scanner-result">扫描 {{scanResult.scanned}} 台 · 发现 node_exporter {{scanResult.found}} 台 · 新纳管 {{scanResult.adopted}} · 合并刷新 {{scanResult.merged}} · 重复/冲突 {{scanResult.conflicts}}</div></section><section v-if="activeTab==='discovery'" class="discovery-panel ssh-scanner"><header><div><h2>SSH 采集</h2><span>对无法安装 Agent 的主机，通过 SSH 采集并入 CMDB（凭据在服务端 Secret 配置）</span></div></header><div class="scanner-form"><label><span>主机/网段（每行一个）</span><textarea v-model="sshCidrs" rows="3"></textarea></label><label><span>SSH 端口</span><input v-model.number="sshPort" type="number" min="1" max="65535"></label><label><span>资产类型</span><select v-model="sshScanType"><option value="">自动识别（默认物理机）</option><option value="physical-server">物理服务器</option><option value="virtual-machine">虚拟机</option></select></label><label><span>凭据</span><select v-model="sshCred"><option value="">使用服务端默认</option><option v-for="c in creds.filter(x=>x.kind==='ssh')" :key="c.id" :value="c.id">{{c.name}}</option></select></label><button class="primary" :disabled="sshScanning" @click="scanSSH">{{sshScanning?'采集并纳管中...':'SSH 采集并纳管'}}</button></div><div v-if="sshResult" class="scanner-result">扫描 {{sshResult.scanned}} · 发现 {{sshResult.found}} · 新纳管 {{sshResult.adopted}} · 合并刷新(按IP去重) {{sshResult.merged}} · 重复/冲突 {{sshResult.conflicts}}</div></section><section class="discovery-panel agent-install"><header><div><h2>Agent 批量安装</h2><span>通过 SSH 在目标主机安装并启动 cmdb-agent（二进制由服务端 CMDB_AGENT_BUNDLE_URL 下发）</span></div></header><div class="scanner-form"><label><span>主机 IP（每行一个）</span><textarea v-model="aiHosts" rows="3"></textarea></label><label><span>SSH 端口</span><input v-model.number="aiPort" type="number" min="1" max="65535"></label><label><span>网关地址(安装源)</span><input v-model="aiGateway" placeholder="http://节点IP:30080"></label><label><span>资产类型</span><select v-model="aiType"><option value="">自动识别（默认物理机）</option><option value="physical-server">物理服务器</option><option value="virtual-machine">虚拟机</option></select></label><label><span>凭据</span><select v-model="aiCred"><option value="">使用服务端默认</option><option v-for="c in creds.filter(x=>x.kind==='ssh')" :key="c.id" :value="c.id">{{c.name}}</option></select></label><button class="primary" :disabled="aiBusy" @click="batchInstall">{{aiBusy?'安装/升级中...':`批量安装/升级 Agent${aiVersion?(' (v'+aiVersion+')'):''}`}}</button>
          <button class="primary danger" :disabled="aiBusy" @click="batchUninstall">批量卸载 Agent</button></div><div class="ai-results"><p v-for="r in aiResult" :key="r.host" :class="{ok:r.ok}">{{r.host}} → {{r.ok?'成功':'失败'}} · {{r.info}}</p></div></section><div v-if="selectedAgent" class="modal-backdrop"><section class="agent-detail"><header><div><span>AGENT DETAIL</span><h2>{{selectedAgent.name || selectedAgent.hostname}}</h2></div><button @click="closeAgent">✕</button></header><dl><dt>Agent ID</dt><dd>{{selectedAgent.id}}</dd><dt>主机名</dt><dd>{{selectedAgent.hostname}}</dd><dt>IP</dt><dd>{{selectedAgent.ip}}</dd><dt>操作系统</dt><dd>{{selectedAgent.os||'-'}}</dd><dt>区域</dt><dd>{{selectedAgent.region||'-'}}</dd><dt>版本</dt><dd>v{{selectedAgent.version}}</dd><dt>状态</dt><dd>{{selectedAgent.status}}</dd><dt>最近心跳</dt><dd>{{selectedAgent.lastHeartbeat}}</dd><template v-if="agentAsset"><dt>CMDB 类型</dt><dd>{{agentAsset.typeName}}</dd><dt>负责人</dt><dd>{{agentAsset.owner}}</dd><dt>项目组</dt><dd>{{agentAsset.projectGroup}}</dd></template></dl></section></div><section v-if="activeTab==='network'" class="discovery-panel snmp-scanner"><header><div><h2>SNMP 网络设备采集</h2><span>扫描网络设备的只读 community（服务端配置），发现即纳管为 network-device</span></div></header><div class="scanner-form"><label><span>网段（每行一个）</span><textarea v-model="snmpCidrs" rows="3"></textarea></label><label><span>SNMP 端口</span><input v-model.number="snmpPort" type="number" min="1" max="65535"></label><label><span>资产类型</span><select v-model="snmpType"><option value="">自动识别(网络设备/带外服务器)</option><option value="network-device">网络设备</option><option value="physical-server">服务器(带外)</option></select></label><label><span>凭据</span><select v-model="snmpCred"><option value="">使用服务端默认</option><option v-for="c in creds.filter(x=>x.kind==='snmp')" :key="c.id" :value="c.id">{{c.name}}</option></select></label><button class="primary" :disabled="snmpBusy" @click="scanSNMP">{{snmpBusy?'扫描中...':'SNMP 扫描并纳管'}}</button></div><div v-if="snmpResult" class="scanner-result">扫描 {{snmpResult.scanned}} · 发现设备 {{snmpResult.found}} · 新纳管 {{snmpResult.adopted}} · 合并 {{snmpResult.merged}} · 冲突 {{snmpResult.conflicts}}</div></section><div v-if="showCreds" class="modal-backdrop"><section class="asset-editor"><header><div><span>VAULT CREDENTIALS</span><h2>凭据管理</h2></div><button @click="showCreds=false">✕</button></header><div class="editor-grid"><label><span>名称</span><input v-model="credName"></label><label><span>类型</span><select v-model="credKind"><option value="ssh">SSH</option><option value="snmp">SNMP</option></select></label><label><span>用户名</span><input v-model="credUser"></label><label><span>密码/Community</span><input v-model="credSecret" type="password"></label></div><footer><button @click="showCreds=false">关闭</button><button class="primary" @click="addCred">保存到 Vault</button></footer><ul><li v-for="c in creds" :key="c.id">{{c.kind}} · {{c.name}} ({{c.username||'-'}}) <button @click="removeCred(c.id)">删除</button></li></ul></section></div><div v-if="showApprovals" class="modal-backdrop"><section class="asset-editor"><header><div><span>APPROVAL & AUDIT</span><h2>待审批 / 审计日志</h2></div><button @click="showApprovals=false">✕</button></header><h3>待审批 ({{pending.length}})</h3><div v-if="approvalMessage" class="scanner-result">{{approvalMessage}}</div><ul class="pending-list"><li v-for="p in pending" :key="p.id"><span>{{p.source}} · {{p.name}} ({{p.ip}}) → {{p.type}}<small>{{p.confidence}}% · {{p.discoveredAt}}</small></span><button :disabled="actionBusy===p.id" @click="approveItem(p.id)">通过</button><button :disabled="actionBusy===p.id" @click="rejectItem(p.id)">拒绝</button></li><li v-if="!pending.length">暂无待审批</li></ul><h3>审计日志</h3><ul class="audit-list"><li v-for="a in audit" :key="a.id">{{a.occurredAt}} · {{a.actor}} · {{a.action}} · {{a.target}} {{a.detail}}</li><li v-if="!audit.length">暂无审计记录</li></ul></section></div><RemoteExecutionPanel v-if="activeTab==='operations'"/><RemoteAccessPanel v-if="activeTab==='operations'"/><KubernetesPanel v-if="activeTab==='k8s'"/><ExporterPanel v-if="activeTab==='exporter'"/></div><TaskResultModal v-if="selectedTaskId" :task-id="selectedTaskId" @close="selectedTaskId=''"/></section></template>

